style.css:
@-moz-document domain("youtube.com") {
/* Main Background to Pure Black */
    html, [theme="dark"], body {
        background-color: #000000 !important;
    }

    ytd-app, 
    ytd-masthead, 
    #contentContainer.ytd-app,
    #page-manager.ytd-app {
        background: #000000 !important;
    }

    /* Side bar and Header adjustments */
    #guide-content.ytd-guide-renderer,
    ytd-mini-guide-renderer.ytd-app,
    #background.ytd-masthead {
        background-color: #0d0d0d !important;
    }

    /* Search bar darkening */
    #container.ytd-searchbox,
    #search-icon-legacy.ytd-searchbox {
        background-color: #1a1a1a !important;
        border: 1px solid #333 !important;
    }

    /* Desaturating the Red Highlights (Branding) */
    .yt-spec-icon-shape, 
    #logo-icon,
    .style-scope.ytd-topbar-logo-renderer {
        filter: saturate(0.5) contrast(1.2) !important;
    }

    /* Video Player Progress Bar - Softer Red */
    .ytp-swatch-background-color {
        background-color: #b32d2d !important;
    }

    /* Text contrast improvements */
    #video-title, #description-text, #content-text {
        color: #e0e0e0 !important;
    }
}
